add_filter( 'block_editor_settings_all', 'perfectpixel_restrict_code_editor', 20 );

function perfectpixel_restrict_code_editor( $settings ) {
	$cap = trim( '{{code_editor_capability}}' );
	if ( ! current_user_can( $cap ? $cap : 'manage_options' ) ) {
		$settings['codeEditingEnabled'] = false;
	}
	return $settings;
}
